import Foundation
import Testing

@testable import App
@testable import Macarchy

extension WebInterfaceTests {
    /// Setup moving an earlier bar onto widgets, in the parent's isolated
    /// environment without a web view.
    @MainActor
    @Suite("Setup moving the bar onto widgets")
    struct BarMoveSetupTests {
        /// A generated sketchybarrc from before widgets, with `region` kept.
        private func earlierRC(_ region: String) -> String {
            """
            #!/bin/bash
            # Generated by Macarchy. The bar comes from the Menu Bar page and the active theme.
            #
            # >>> macarchy:keep yours
            \(region)
            # <<< macarchy:keep

            "$HOME/Library/Application Support/Macarchy/Macarchy.app/Contents/MacOS/macarchy" startup sketchybar

            sketchybar --update

            """
        }

        private func component(_ id: String, _ title: String, visible: Bool) -> BarComponent {
            BarComponent(id: id, title: title, side: "right", members: [id], visible: visible)
        }

        /// Writes settings an earlier version saved: whose bar ran, and the bar.
        private func saveEarlier(
            _ harness: Harness, bundled: Bool, bar: BarConfiguration?
        ) throws {
            try harness.store.update { $0.barConfiguration = bar }
            var json =
                try JSONSerialization.jsonObject(with: harness.settingsData) as? [String: Any]
                ?? [:]
            json["bundledBar"] = bundled
            try JSONSerialization.data(withJSONObject: json).write(to: harness.store.url)
        }

        /// An earlier own bar: a hidden helper, an item no widget replaces,
        /// a clock and a command item, built by `region`.
        private func saveOwnBar(_ harness: Harness, region: String) throws {
            var command = component("macarchy.uptime", "Uptime", visible: true)
            command.kind = "command"
            command.command = "uptime"
            command.interval = 60
            var bar = BarConfiguration()
            bar.components = [
                component("theme_listener", "Theme Listener", visible: false),
                component("weather", "Weather", visible: true),
                component("calendar", "Clock", visible: true), command
            ]
            try saveEarlier(harness, bundled: false, bar: bar)
            try harness.write(
                earlierRC(region), to: "Library/Application Support/Macarchy/config/sketchybarrc")
        }

        private func expectReported(_ lines: [String]) {
            let text = lines.joined(separator: "\n")
            #expect(text.contains("Saved the menu bar as it was in snapshot"))
            #expect(text.contains("Your own bar no longer runs"))
            #expect(text.contains("Clock now shows a built-in widget"))
            #expect(text.contains("Made scripted widgets from your command items"))
            #expect(text.contains("Removed hidden items left from the earlier bar: Theme Listener"))
            #expect(text.contains("No widget replaces Weather"))
        }

        /// The settings the snapshot taken before the move holds.
        private func settingsBeforeMove() throws -> String {
            let store = SnapshotStore()
            let snapshot = try #require(
                store.list().first { store.reason(for: $0).contains("onto widgets") })
            return try String(
                contentsOf: snapshot.url.appending(path: snapshot.files[0]), encoding: .utf8)
        }

        @Test("a person's own bar becomes widgets after a snapshot, with its commands kept aside")
        func ownBar() async throws {
            try await withHarness(tools: []) { harness in
                try await withSetupResources(harness) {
                    let region = "sketchybar --remove '/.*/'\nsketchybar --add item weather right"
                    try saveOwnBar(harness, region: region)
                    #expect(Setup.barNeedsMoving && harness.model.shellState().setupRequired)
                    #expect(
                        Setup.plan(existing: .keep).contains {
                            $0.path == Paths.settings && $0.detail.contains("onto widgets")
                        })

                    let report = await harness.model.setupSession.run(existing: .keep, app: nil)
                    #expect(report.failure == nil)
                    expectReported(report.lines)

                    let settings = try harness.store.read()
                    #expect(settings.unknownKeys["bundledBar"] == nil)
                    let components = try #require(settings.barConfiguration).components
                    #expect(components.map(\.id) == ["macarchy.clock", "macarchy.uptime"])
                    let allWidgets = components.allSatisfy { $0.isWidget }
                    #expect(allWidgets)
                    let provider = Paths.widgetsDirectory.appending(path: "uptime/provider.sh")
                    #expect(FileManager.default.fileExists(atPath: provider.path))
                    let kept = try String(contentsOf: Setup.ownBarArchive, encoding: .utf8)
                    #expect(kept.contains(region))
                    let rc = try String(
                        contentsOf: StartupConfiguration.sketchybarrc.url, encoding: .utf8)
                    #expect(!rc.contains("add item weather"))
                    #expect(
                        try #require(rc.range(of: "startup sketchybar")).lowerBound
                            < (try #require(rc.range(of: "macarchy:keep yours")).lowerBound))
                    #expect(try settingsBeforeMove().contains("\"bundledBar\""))
                    #expect(!Setup.barNeedsMoving && !harness.model.shellState().setupRequired)

                    let again = await harness.model.setupSession.run(existing: .keep, app: nil)
                    #expect(again.failure == nil)
                    #expect(!again.lines.contains { $0.contains("widget") })
                    #expect(try harness.store.read().barConfiguration?.components == components)
                }
            }
        }

        @Test("Macarchy's earlier bar becomes the widget layout and keeps the person's region")
        func bundledBar() async throws {
            try await withHarness(tools: []) { harness in
                try await withSetupResources(harness) {
                    try saveEarlier(harness, bundled: true, bar: nil)
                    try harness.write(
                        earlierRC("sketchybar --add item mine right"),
                        to: "Library/Application Support/Macarchy/config/sketchybarrc")
                    let report = await harness.model.setupSession.run(existing: .keep, app: nil)
                    #expect(report.failure == nil)
                    let bar = try #require(try harness.store.read().barConfiguration)
                    #expect(
                        bar.components.map(\.id)
                            == BarConfiguration.widgetDefault.components.map(\.id))
                    #expect(report.lines.contains("Moved the menu bar onto Macarchy's widgets"))
                    #expect(!FileManager.default.fileExists(atPath: Setup.ownBarArchive.path))
                    let rc = try String(
                        contentsOf: StartupConfiguration.sketchybarrc.url, encoding: .utf8)
                    #expect(rc.contains("sketchybar --add item mine right"))
                }
            }
        }

        @Test(
            "a new install gets the widget layout, and a sketchybarrc of the person's own is left")
        func newInstall() async throws {
            try await withHarness(tools: []) { harness in
                try await withSetupResources(harness) {
                    let own = "#!/usr/bin/env lua\nsbar = require(\"sketchybar\")\n"
                    try harness.write(own, to: ".config/sketchybar/sketchybarrc")
                    #expect(!Setup.barNeedsMoving)
                    let report = await harness.model.setupSession.run(existing: .keep, app: nil)
                    #expect(report.failure == nil)
                    let bar = try #require(try harness.store.read().barConfiguration)
                    #expect(
                        bar.components.map(\.widget)
                            == BarConfiguration.widgetDefault.components.map(\.widget))
                    // Two-line widgets are saved with the items they draw.
                    let cpu = try #require(bar.components.first { $0.widget == "cpu" })
                    #expect(cpu.members == WidgetLook.stackedMembers(cpu.id))
                    #expect(report.lines.contains("Set up the menu bar with Macarchy's widgets"))
                    #expect(
                        report.lines.contains {
                            $0.hasPrefix("Left ~/.config/sketchybar/sketchybarrc as it is")
                        })
                    #expect(
                        try String(
                            contentsOf: harness.home.appending(
                                path: ".config/sketchybar/sketchybarrc"),
                            encoding: .utf8) == own)
                }
            }
        }
    }
}
